import java.util.Deque;
import java.util.LinkedList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        // 1. Using LinkedList as a Deque (Double-Ended Queue)
        Deque<String> deque = new LinkedList<>();

        // O(1) Operations on Head and Tail
        deque.addFirst("Middle");
        deque.addFirst("Front");
        deque.addLast("Back");
        System.out.println("Deque state: " + deque);

        System.out.println("Peek Head: " + deque.peekFirst());
        System.out.println("Peek Tail: " + deque.peekLast());

        System.out.println("Poll Front: " + deque.pollFirst()); // O(1) removal
        System.out.println("After Poll: " + deque);

        // 2. The O(n) Index Access Trap (Antipattern)
        List<Integer> list = new LinkedList<>();
        for (int i = 0; i < 5; i++) { list.add(i * 10); }

        System.out.println("\n=== Index-based Traversal ===");
        // WARNING: In a large LinkedList, calling get(i) in a for-loop results in O(n^2)!
        for (int i = 0; i < list.size(); i++) {
            System.out.println("Index " + i + ": " + list.get(i));
        }
    }
}

