class SimpleNode {
    String data;
    SimpleNode prev;
    SimpleNode next;

    public SimpleNode(String data) {
        this.data = data;
    }
}

public class Main {
    public static void main(String[] args) {
        SimpleNode n1 = new SimpleNode("A");
        SimpleNode n2 = new SimpleNode("B");
        SimpleNode n3 = new SimpleNode("C");

        // Link doubly
        n1.next = n2; n2.prev = n1;
        n2.next = n3; n3.prev = n2;

        // Forward
        System.out.print("Forward: ");
        SimpleNode curr = n1;
        while (curr != null) {
            System.out.print(curr.data + (curr.next != null ? " <-> " : ""));
            curr = curr.next;
        }
        System.out.println();

        // Backward
        System.out.print("Backward: ");
        curr = n3;
        while (curr != null) {
            System.out.print(curr.data + (curr.prev != null ? " <-> " : ""));
            curr = curr.prev;
        }
        System.out.println();
    }
}

